127	                // Touch/swipe support for mobile
128	            }
129	
130	            setupProgressBar() {
131	                // Update progress bar on scroll
132	            }
133	
134	            setupNavDots() {
135	                // Generate and manage navigation dots
136	            }
137	        }
138	
139	        new SlidePresentation();
140	    </script>
141	</body>
142	</html>
143	```
144	
145	## Required JavaScript Features
146	
147	Every presentation must include:
148	
149	1. **SlidePresentation Class** — Main controller with:
150	   - Keyboard navigation (arrows, space, page up/down)
151	   - Touch/swipe support
152	   - Mouse wheel navigation
153	   - Progress bar updates
154	   - Navigation dots
155	
156	2. **Intersection Observer** — For scroll-triggered animations:
157	   - Add `.visible` class when slides enter viewport
158	   - Trigger CSS transitions efficiently
159	
160	3. **Optional Enhancements** (match to chosen style):
161	   - Custom cursor with trail
162	   - Particle system background (canvas)
163	   - Parallax effects
164	   - 3D tilt on hover
165	   - Magnetic buttons
166	   - Counter animations
167	
168	4. **Inline Editing** (only if user opted in during Phase 1 — skip entirely if they said No):
169	   - Edit toggle button (hidden by default, revealed via hover hotzone or `E` key)
170	   - Auto-save to localStorage
171	   - Export/save file functionality
172	   - See "Inline Editing Implementation" section below
173	
174	## Inline Editing Implementation (Opt-In Only)
175	
176	**If the user chose "No" for inline editing in Phase 1, do NOT generate any edit-related HTML, CSS, or JS.**
177	
178	**Do NOT use CSS `~` sibling selector for hover-based show/hide.** The CSS-only approach (`edit-hotzone:hover ~ .edit-toggle`) fails because `pointer-events: none` on the toggle button breaks the hover chain: user hovers hotzone -> button becomes visible -> mouse moves toward button -> leaves hotzone -> button disappears before click.
179	
180	**Required approach: JS-based hover with 400ms delay timeout.**
181	
182	HTML:
183	```html
184	<div class="edit-hotzone"></div>
185	<button class="edit-toggle" id="editToggle" title="Edit mode (E)">✏️</button>
186	```
187	
188	CSS (visibility controlled by JS classes only):
189	```css
190	/* Do NOT use CSS ~ sibling selector for this!
191	   pointer-events: none breaks the hover chain.
192	   Must use JS with delay timeout. */
193	.edit-hotzone {
194	    position: fixed; top: 0; left: 0;
195	    width: 80px; height: 80px;
196	    z-index: 10000;
197	    cursor: pointer;
198	}
199	.edit-toggle {
200	    opacity: 0;
201	    pointer-events: none;
202	    transition: opacity 0.3s ease;
203	    z-index: 10001;
204	}
205	.edit-toggle.show,
206	.edit-toggle.active {
207	    opacity: 1;
208	    pointer-events: auto;
209	}
210	```
211	
212	JS (three interaction methods):
213	```javascript
214	// 1. Click handler on the toggle button
215	document.getElementById('editToggle').addEventListener('click', () => {
216	    editor.toggleEditMode();
217	});
218	
219	// 2. Hotzone hover with 400ms grace period
220	const hotzone = document.querySelector('.edit-hotzone');
221	const editToggle = document.getElementById('editToggle');
222	let hideTimeout = null;
223	
224	hotzone.addEventListener('mouseenter', () => {
225	    clearTimeout(hideTimeout);
226	    editToggle.classList.add('show');
227	});
228	hotzone.addEventListener('mouseleave', () => {
229	    hideTimeout = setTimeout(() => {
230	        if (!editor.isActive) editToggle.classList.remove('show');
231	    }, 400);
232	});
233	editToggle.addEventListener('mouseenter', () => {
234	    clearTimeout(hideTimeout);
235	});
236	editToggle.addEventListener('mouseleave', () => {
237	    hideTimeout = setTimeout(() => {
238	        if (!editor.isActive) editToggle.classList.remove('show');
239	    }, 400);
240	});
241	
242	// 3. Hotzone direct click
243	hotzone.addEventListener('click', () => {
244	    editor.toggleEditMode();
245	});
246	
247	// 4. Keyboard shortcut (E key, skip when editing text)
248	document.addEventListener('keydown', (e) => {
249	    if ((e.key === 'e' || e.key === 'E') && !e.target.getAttribute('contenteditable')) {
250	        editor.toggleEditMode();
251	    }
252	});
253	```
254	
255	## Image Pipeline (Skip If No Images)
256	
257	If user chose "No images" in Phase 1, skip this entirely. If images were provided, process them before generating HTML.
258	
259	**Dependency:** `pip install Pillow`
260	
261	### Image Processing
262	
263	```python
264	from PIL import Image, ImageDraw
265	
266	# Circular crop (for logos on modern/clean styles)
267	def crop_circle(input_path, output_path):
268	    img = Image.open(input_path).convert('RGBA')
269	    w, h = img.size
270	    size = min(w, h)
271	    left, top = (w - size) // 2, (h - size) // 2
272	    img = img.crop((left, top, left + size, top + size))
273	    mask = Image.new('L', (size, size), 0)
274	    ImageDraw.Draw(mask).ellipse([0, 0, size, size], fill=255)
275	    img.putalpha(mask)
276	    img.save(output_path, 'PNG')
277	
278	# Resize (for oversized images that inflate HTML)
279	def resize_max(input_path, output_path, max_dim=1200):
280	    img = Image.open(input_path)
281	    img.thumbnail((max_dim, max_dim), Image.LANCZOS)
282	    img.save(output_path, quality=85)
283	```
284	
285	| Situation | Operation |
286	|-----------|-----------|
287	| Square logo on rounded aesthetic | `crop_circle()` |
288	| Image > 1MB | `resize_max(max_dim=1200)` |
289	| Wrong aspect ratio | Manual crop with `img.crop()` |
290	
291	Save processed images with `_processed` suffix. Never overwrite originals.
292	
293	### Image Placement
294	
295	**Use direct file paths** (not base64) — presentations are viewed locally:
296	
297	```html
298	<img src="assets/logo_round.png" alt="Logo" class="slide-image logo">
299	<img src="assets/screenshot.png" alt="Screenshot" class="slide-image screenshot">
300	```
301	
302	```css
303	.slide-image {
304	    max-width: 100%;
305	    max-height: min(50vh, 400px);
306	    object-fit: contain;
307	    border-radius: 8px;
308	}
309	.slide-image.screenshot {
310	    border: 1px solid rgba(255, 255, 255, 0.1);
311	    border-radius: 12px;
312	    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.3);
313	}
314	.slide-image.logo {
315	    max-height: min(30vh, 200px);
316	}
317	```
318	
319	**Adapt border/shadow colors to match the chosen style's accent.** Never repeat the same image on multiple slides (except logos on title + closing).
320	
321	**Placement patterns:** Logo centered on title slide. Screenshots in two-column layouts with text. Full-bleed images as slide backgrounds with text overlay (use sparingly).
322	
323	---
324	
325	## Code Quality
326	
327	**Comments:** Every section needs clear comments explaining what it does and how to modify it.
328	
329	**Accessibility:**
330	- Semantic HTML (`<section>`, `<nav>`, `<main>`)
331	- Keyboard navigation works fully
332	- ARIA labels where needed
333	- `prefers-reduced-motion` support (included in viewport-base.css)
334	
335	## File Structure
336	
337	Single presentations:
338	```
339	presentation.html    # Self-contained, all CSS/JS inline
340	assets/              # Images only, if any
341	```
342	
343	Multiple presentations in one project:
344	```
345	[name].html
346	[name]-assets/
347	```
