    <link href="https://fonts.googleapis.com/css2?family=Archivo:wght@400;500;600;700;800&family=DM+Sans:wght@400;500;600&family=Space+Grotesk:wght@400;500;600;700&display=swap" rel="stylesheet">

    <style>
        /* ===========================================
           VIEWPORT FITTING: MANDATORY BASE STYLES
           =========================================== */
        html, body {
            height: 100%;
            overflow-x: hidden;
        }
        html {
            scroll-snap-type: y mandatory;
            scroll-behavior: smooth;
        }

        .slide {
            width: 100vw;
            height: 100vh;
            height: 100dvh;
            overflow: hidden;
            scroll-snap-align: start;
            display: flex;
            flex-direction: column;
            position: relative;
        }

        .slide-content {
            flex: 1;
            display: flex;
            flex-direction: column;
            justify-content: center;
            max-height: 100%;
            overflow: hidden;
            padding: var(--slide-padding);
        }

        :root {
            --title-size: clamp(1.5rem, 5vw, 3.5rem);
            --h2-size: clamp(1.25rem, 3.5vw, 2.5rem);
            --h3-size: clamp(1rem, 2.5vw, 1.5rem);
            --body-size: clamp(0.75rem, 1.5vw, 1.1rem);
            --small-size: clamp(0.65rem, 1vw, 0.875rem);
            --slide-padding: clamp(1rem, 4vw, 3.5rem);
            --content-gap: clamp(0.5rem, 2vw, 1.5rem);
            --element-gap: clamp(0.25rem, 1vw, 0.75rem);

            /* Theme: Professional Energy Analytics */
            --bg-primary: #0c1a1f;
            --bg-secondary: #122530;
            --bg-card: #1a3441;
            --text-primary: #f0f4f8;
            --text-secondary: #8fa5b0;
            --accent-green: #2dd4a8;
            --accent-teal: #0d9488;
            --accent-amber: #f59e0b;
            --accent-red: #ef4444;
            --accent-solar: #fbbf24;
            --accent-wind: #60a5fa;

            --font-display: 'Archivo', sans-serif;
            --font-body: 'DM Sans', sans-serif;
            --font-mono: 'Space Grotesk', monospace;

            --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
            --duration-normal: 0.6s;
        }

        /* ===========================================
           BASE STYLES
           =========================================== */
        * { margin: 0; padding: 0; box-sizing: border-box; }

        body {
            font-family: var(--font-body);
            background: var(--bg-primary);
            color: var(--text-primary);
            line-height: 1.5;
        }

        /* ===========================================
           ANIMATIONS
           =========================================== */
        .reveal {
            opacity: 0;
            transform: translateY(25px);
            transition: opacity var(--duration-normal) var(--ease-out-expo),
                        transform var(--duration-normal) var(--ease-out-expo);
        }

        .slide.visible .reveal {
            opacity: 1;
            transform: translateY(0);
        }

        .reveal:nth-child(1) { transition-delay: 0.05s; }
        .reveal:nth-child(2) { transition-delay: 0.15s; }
        .reveal:nth-child(3) { transition-delay: 0.25s; }
        .reveal:nth-child(4) { transition-delay: 0.35s; }
        .reveal:nth-child(5) { transition-delay: 0.45s; }
        .reveal:nth-child(6) { transition-delay: 0.55s; }

        /* ===========================================
           SLIDE LAYOUTS
           =========================================== */

        /* Title Slide */
        .slide-title {
            background: linear-gradient(135deg, var(--bg-primary) 0%, var(--bg-secondary) 50%, var(--bg-primary) 100%);
            justify-content: center;
            align-items: center;
            text-align: center;
            position: relative;
        }

        .slide-title::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background:
                radial-gradient(ellipse at 20% 80%, rgba(45, 212, 168, 0.08) 0%, transparent 50%),
                radial-gradient(ellipse at 80% 20%, rgba(13, 148, 136, 0.08) 0%, transparent 50%);
            pointer-events: none;
        }

        .slide-title .title-content {
            position: relative;
            z-index: 1;
            max-width: min(90vw, 1000px);
        }

        .slide-title h1 {
            font-family: var(--font-display);
            font-size: var(--title-size);
            font-weight: 800;
            line-height: 1.1;
            margin-bottom: var(--content-gap);
            background: linear-gradient(135deg, var(--text-primary) 0%, var(--accent-green) 100%);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
        }

        .slide-title .subtitle {
            font-size: clamp(0.9rem, 2vw, 1.25rem);
            color: var(--text-secondary);
            margin-bottom: var(--element-gap);
        }

        .slide-title .source {
            font-size: var(--small-size);
            color: var(--text-secondary);
            opacity: 0.7;
            margin-top: var(--content-gap);
        }

        /* Content Slide */
        .slide-content-main {
            background: var(--bg-primary);
        }

        .slide h2 {
            font-family: var(--font-display);
            font-size: var(--h2-size);
            font-weight: 700;
            color: var(--text-primary);
            margin-bottom: var(--content-gap);
            line-height: 1.2;
        }

        .slide h2 .stat {
            color: var(--accent-green);
        }

        .slide p {
            font-size: var(--body-size);
            color: var(--text-secondary);
            max-width: 70ch;
        }

        /* Stat Cards */
        .stat-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(min(100%, 200px), 1fr));
            gap: var(--content-gap);
            margin-top: var(--content-gap);
        }

        .stat-card {
            background: var(--bg-card);
            border-radius: 12px;
            padding: clamp(1rem, 2vw, 1.5rem);
            border: 1px solid rgba(45, 212, 168, 0.1);
            position: relative;
            overflow: hidden;
        }

        .stat-card::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            width: 4px;
            height: 100%;
            background: var(--accent-green);
        }

        .stat-card.red::before { background: var(--accent-red); }
        .stat-card.amber::before { background: var(--accent-amber); }
        .stat-card.teal::before { background: var(--accent-teal); }
        .stat-card.solar::before { background: var(--accent-solar); }
        .stat-card.wind::before { background: var(--accent-wind); }

        .stat-card .number {
            font-family: var(--font-display);
            font-size: clamp(1.5rem, 4vw, 2.5rem);
            font-weight: 700;
            color: var(--text-primary);
        }

        .stat-card .label {
            font-size: var(--small-size);
            color: var(--text-secondary);
            margin-top: 0.25rem;
        }

        /* Data Table */
        .data-table {
            background: var(--bg-card);
            border-radius: 12px;
            overflow: hidden;
            margin-top: var(--content-gap);
            max-width: min(80vw, 700px);
        }

        .data-table table {
            width: 100%;
            border-collapse: collapse;
            font-size: var(--body-size);
        }

        .data-table th {
            background: rgba(45, 212, 168, 0.1);
            color: var(--accent-green);
            font-weight: 600;
            text-align: left;
            padding: clamp(0.5rem, 1.5vw, 1rem);
        }

        .data-table td {
            padding: clamp(0.5rem, 1.5vw, 1rem);
            border-bottom: 1px solid rgba(255, 255, 255, 0.05);
            color: var(--text-primary);
        }

        .data-table tr:last-child td {
            border-bottom: none;
        }

        .data-table td:last-child {
            text-align: right;
            font-weight: 600;
        }

        .data-table .highlight {
            color: var(--accent-green);
        }

        /* Bar Chart */
        .bar-chart {
            display: flex;
            flex-direction: column;
            gap: clamp(0.5rem, 1.5vw, 1rem);
            margin-top: var(--content-gap);
            max-width: min(80vw, 600px);
        }

        .bar-row {
            display: flex;
            align-items: center;
            gap: clamp(0.5rem, 1.5vw, 1rem);
        }

        .bar-label {
            font-size: var(--small-size);
            color: var(--text-secondary);
            width: 80px;
            flex-shrink: 0;
        }

        .bar-track {
            flex: 1;
            height: clamp(1rem, 3vh, 1.5rem);
            background: var(--bg-secondary);
            border-radius: 8px;
            overflow: hidden;
            position: relative;
        }

        .bar-fill {
            height: 100%;
            border-radius: 8px;
            transition: width 1s var(--ease-out-expo);
        }

        .bar-fill.hydro { background: linear-gradient(90deg, var(--accent-teal), var(--accent-green)); }
        .bar-fill.wind { background: linear-gradient(90deg, var(--accent-wind), #93c5fd); }
        .bar-fill.solar { background: linear-gradient(90deg, var(--accent-solar), #fde68a); }
        .bar-fill.other { background: linear-gradient(90deg, #6b7280, #9ca3af); }

        .bar-value {
            font-size: var(--small-size);
            color: var(--text-primary);
            font-weight: 600;
            width: 70px;
            text-align: right;
            flex-shrink: 0;
        }

        /* Image Slide */
        .slide-image {
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
        }

        .slide-image img {
            max-width: 100%;
            max-height: min(55vh, 450px);
            object-fit: contain;
            border-radius: 12px;
            border: 1px solid rgba(255, 255, 255, 0.1);
            box-shadow: 0 8px 32px rgba(0, 0, 0, 0.3);
        }

        .slide-image h2 {
            text-align: center;
        }

        /* Two Column */
        .two-col {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: var(--content-gap);
            align-items: start;
        }

        @media (max-width: 768px) {
            .two-col { grid-template-columns: 1fr; }
        }

        /* Bullet List */
        .bullet-list {
            list-style: none;
            display: flex;
            flex-direction: column;
            gap: var(--element-gap);
        }

        .bullet-list li {
            display: flex;
            align-items: flex-start;
            gap: clamp(0.5rem, 1vw, 0.75rem);
            font-size: var(--body-size);
            color: var(--text-primary);
        }

        .bullet-list li::before {
            content: '';
            width: 8px;
            height: 8px;
            background: var(--accent-green);
            border-radius: 50%;
            margin-top: 0.5em;
            flex-shrink: 0;
        }

        .bullet-list li.red::before { background: var(--accent-red); }
        .bullet-list li.amber::before { background: var(--accent-amber); }

        /* Takeaway Grid */
        .takeaway-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(min(100%, 280px), 1fr));
            gap: var(--content-gap);
            margin-top: var(--content-gap);
        }

        .takeaway-card {
            background: var(--bg-card);
            border-radius: 12px;
            padding: clamp(1rem, 2vw, 1.5rem);
            border: 1px solid rgba(45, 212, 168, 0.1);
        }

        .takeaway-card h3 {
            font-family: var(--font-display);
            font-size: var(--h3-size);
            color: var(--accent-green);
            margin-bottom: var(--element-gap);
        }

        .takeaway-card p {
            font-size: var(--small-size);
        }

        /* Progress bar */
        .progress-bar {
            position: fixed;
            top: 0;
            left: 0;
            height: 3px;
            background: var(--accent-green);
            width: 0%;
            z-index: 1000;
            transition: width 0.3s ease;
        }

        /* Nav dots */
        .nav-dots {
            position: fixed;
            right: clamp(0.5rem, 2vw, 1.5rem);
            top: 50%;
            transform: translateY(-50%);
            display: flex;
            flex-direction: column;
            gap: 8px;
            z-index: 100;
        }

        .nav-dot {
            width: 8px;
            height: 8px;
            border-radius: 50%;
            background: rgba(255, 255, 255, 0.2);
            cursor: pointer;
            transition: all 0.3s ease;
        }

        .nav-dot.active {
            background: var(--accent-green);
            transform: scale(1.3);
        }

        /* Comparison Table */
        .comparison-table {
            background: var(--bg-card);
            border-radius: 12px;
            overflow: hidden;
            margin-top: var(--content-gap);
            max-width: min(80vw, 600px);
        }

        .comparison-table table {
            width: 100%;
            border-collapse: collapse;
            font-size: var(--body-size);
        }

        .comparison-table th {
            background: rgba(45, 212, 168, 0.1);
            color: var(--accent-green);
            font-weight: 600;
            padding: clamp(0.75rem, 1.5vw, 1rem);
            text-align: center;
        }

        .comparison-table th:first-child {
            text-align: left;
        }

        .comparison-table td {
            padding: clamp(0.75rem, 1.5vw, 1rem);
            border-bottom: 1px solid rgba(255, 255, 255, 0.05);
            text-align: center;
        }

        .comparison-table td:first-child {
            text-align: left;
            font-weight: 500;
        }

        .comparison-table tr:last-child td {
            border-bottom: none;
        }

        .comparison-table .wind-color { color: var(--accent-wind); font-weight: 600; }
        .comparison-table .solar-color { color: var(--accent-solar); font-weight: 600; }

        /* ===========================================
           RESPONSIVE BREAKPOINTS
           =========================================== */
        @media (max-height: 700px) {
            :root {
                --slide-padding: clamp(0.75rem, 3vw, 2rem);
